def starting_sheets(apps, schema_editor):
    """Give the case types PHAEMA ships with their starting property parts and checklists. Case types a council
    added keep the general default and start with no checklist."""
    from apps.cases import seed

    CaseType = apps.get_model("cases", "CaseType")
    Item = apps.get_model("cases", "CaseTypeChecklistItem")
    shipped = {code: group for code, _name, group, *_rest in seed.TYPES}
    for case_type in CaseType.objects.filter(code__in=shipped):
        case_type.visit_parts = seed.visit_parts_for(case_type.code, shipped[case_type.code])
        case_type.save(update_fields=["visit_parts"])
        seed.add_checklist(case_type, Item)


